def sum_of_digits(numbers):
    def safe_digit_sum(num):
        if isinstance(num, int) and num >= 0:  # Ensure num is a non-negative integer
            return sum(int(digit) for digit in str(num))
        elif isinstance(num, str) and num.isdigit():  # Handle numeric strings
            return sum(int(digit) for digit in num)
        return 0  # Ignore invalid or non-numeric values

    return sum(safe_digit_sum(num) for num in numbers if isinstance(num, (int, str)))

# Example tests:
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([10, 20, 4, 5, 'b', 70, 'a']) == 19
assert sum_of_digits([12, '34', -56, None, 'abc', 78]) == 33
